#!/usr/bin/env python3
"""Validate and summarize independent incident-case annotations.

This tool is deliberately descriptive. It does not infer legal compliance,
statistical representativeness, gold labels, or reviewer reliability beyond the
annotated sample.
"""

from __future__ import annotations

import argparse
import csv
import json
import re
import sys
from collections import Counter, defaultdict
from pathlib import Path
from typing import Iterable, Mapping, Sequence

REQUIRED_FIELDS = [
    "reviewer_id",
    "case_id",
    "under_prompt",
    "under_effective_regime",
    "clock_event",
    "harm_status",
    "control_failure",
    "developer_knowledge",
    "needs_confidential_handling",
    "missing_fields",
    "rationale",
    "confidence",
]

ALLOWED = {
    "under_prompt": {"yes", "no", "unclear"},
    "under_effective_regime": {"yes", "no", "unclear"},
    "clock_event": {
        "incident_occurs",
        "deployer_or_contractor_observes",
        "developer_any_team_receives",
        "safety_team_receives",
        "developer_reasonable_suspicion",
        "developer_confirms",
        "unclear",
    },
    "harm_status": {"actual", "potential_only", "none_identified", "uncertain"},
    "control_failure": {"yes", "no", "unclear"},
    "developer_knowledge": {"none", "allegation", "reasonable_suspicion", "confirmed"},
    "needs_confidential_handling": {"yes", "no", "unclear"},
}

REVIEWER_ID_RE = re.compile(r"^[A-Za-z0-9_-]{1,64}$")
MISSING_LABEL_RE = re.compile(r"^[a-z0-9]+(?:_[a-z0-9]+)*$")


class RowError(ValueError):
    """A malformed, unsafe, or semantically invalid annotation row."""


def _clean_label(value: str) -> str:
    return re.sub(r"[\s-]+", "_", value.strip().lower())


def parse_missing_fields(value: str) -> list[str]:
    """Return unique normalized missing-field labels in stable sorted order."""
    labels: set[str] = set()
    for raw_label in value.split(","):
        label = _clean_label(raw_label)
        if not label:
            raise RowError("missing_fields contains an empty label; use 'none' or explicit labels")
        if not MISSING_LABEL_RE.fullmatch(label):
            raise RowError(
                f"invalid missing-field label {raw_label!r}; use short snake_case labels"
            )
        if label == "none":
            if len(value.split(",")) != 1:
                raise RowError("'none' cannot be combined with other missing-field labels")
            continue
        labels.add(label)
    return sorted(labels)


def validate_row(
    row: Mapping[str, str | None],
    valid_case_ids: set[str],
    seen: set[tuple[str, str]] | None = None,
) -> dict[str, str]:
    """Validate one annotation and return a whitespace-normalized copy.

    Reviewer IDs must be pseudonymous handles, not email addresses or free text.
    ``seen`` contains already-observed (reviewer_id, case_id) pairs.
    """
    if None in row:
        raise RowError("row has more cells than the CSV header")
    if set(row) != set(REQUIRED_FIELDS):
        missing = sorted(set(REQUIRED_FIELDS) - set(row))
        extra = sorted(set(row) - set(REQUIRED_FIELDS))
        raise RowError(f"unexpected columns; missing={missing}, extra={extra}")

    clean: dict[str, str] = {}
    for field in REQUIRED_FIELDS:
        value = row.get(field)
        if value is None or not value.strip():
            raise RowError(f"{field} is blank; use a documented category or explicit content")
        clean[field] = value.strip()

    reviewer_id = clean["reviewer_id"]
    if not REVIEWER_ID_RE.fullmatch(reviewer_id) or "@" in reviewer_id:
        raise RowError("reviewer_id must be a pseudonymous 1-64 character handle, not an email")

    if clean["case_id"] not in valid_case_ids:
        raise RowError(f"unknown case_id {clean['case_id']!r}")

    for field, categories in ALLOWED.items():
        if clean[field] not in categories:
            raise RowError(
                f"invalid {field}={clean[field]!r}; expected one of {sorted(categories)}"
            )

    if not re.fullmatch(r"[1-5]", clean["confidence"]):
        raise RowError("confidence must be an integer from 1 through 5")

    if len(clean["rationale"]) < 20:
        raise RowError("rationale must contain enough explanation (at least 20 characters)")

    # Validate and canonicalize labels while retaining a CSV-compatible string.
    clean["missing_fields"] = ",".join(parse_missing_fields(clean["missing_fields"]))
    if not clean["missing_fields"]:
        clean["missing_fields"] = "none"

    pair = (reviewer_id, clean["case_id"])
    if seen is not None and pair in seen:
        raise RowError(f"duplicate annotation for reviewer={reviewer_id!r}, case={pair[1]!r}")
    return clean


def load_case_ids(path: Path) -> set[str]:
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise RowError(f"cannot read case file {path}: {exc}") from exc
    cases = payload.get("cases") if isinstance(payload, dict) else None
    if not isinstance(cases, list) or not cases:
        raise RowError("case file must contain a non-empty 'cases' list")
    ids: list[str] = []
    for index, case in enumerate(cases):
        if not isinstance(case, dict) or not isinstance(case.get("id"), str):
            raise RowError(f"case at index {index} lacks a string id")
        if not case.get("version") or not case.get("facts"):
            raise RowError(f"case {case['id']!r} lacks version or facts")
        ids.append(case["id"])
    if len(ids) != len(set(ids)):
        raise RowError("case file contains duplicate case IDs")
    return set(ids)


def load_annotations(annotation_path: Path, case_path: Path) -> list[dict[str, str]]:
    valid_case_ids = load_case_ids(case_path)
    rows: list[dict[str, str]] = []
    seen: set[tuple[str, str]] = set()
    try:
        handle = annotation_path.open(newline="", encoding="utf-8-sig")
    except OSError as exc:
        raise RowError(f"cannot read annotations {annotation_path}: {exc}") from exc
    with handle:
        reader = csv.DictReader(handle)
        if reader.fieldnames != REQUIRED_FIELDS:
            raise RowError(
                "CSV header must exactly match the annotation template in name and order; "
                f"got {reader.fieldnames!r}"
            )
        for line_number, row in enumerate(reader, start=2):
            try:
                clean = validate_row(row, valid_case_ids, seen)
            except RowError as exc:
                raise RowError(f"CSV line {line_number}: {exc}") from exc
            pair = (clean["reviewer_id"], clean["case_id"])
            seen.add(pair)
            rows.append(clean)
    if not rows:
        raise RowError("annotation file contains no completed annotations")
    return rows


def _counts(values: Iterable[str]) -> dict[str, int]:
    return dict(sorted(Counter(values).items()))


def _field_summary(rows: Sequence[Mapping[str, str]], field: str) -> dict[str, object]:
    counts = _counts(row[field] for row in rows)
    return {
        "counts": counts,
        "distinct_responses": len(counts),
        "disagreement": len(counts) > 1,
    }


def summarize(rows: Sequence[Mapping[str, str]]) -> dict[str, object]:
    """Summarize validated rows without inventing consensus or ground truth."""
    if not rows:
        raise RowError("cannot summarize zero annotations")

    by_case: dict[str, list[Mapping[str, str]]] = defaultdict(list)
    for row in rows:
        by_case[row["case_id"]].append(row)

    case_summaries: dict[str, object] = {}
    for case_id in sorted(by_case):
        case_rows = by_case[case_id]
        fields = {field: _field_summary(case_rows, field) for field in ALLOWED}
        case_summaries[case_id] = {
            "reviewer_count": len({row["reviewer_id"] for row in case_rows}),
            "annotation_count": len(case_rows),
            **fields,
            "reporting_judgment_pairs": _counts(
                f"{row['under_prompt']}|{row['under_effective_regime']}"
                for row in case_rows
            ),
        }

    cases_with_disagreement = {
        field: sum(
            1 for case_id in by_case if len({row[field] for row in by_case[case_id]}) > 1
        )
        for field in ALLOWED
    }
    unclear_rates = {
        field: sum(row[field] in {"unclear", "uncertain"} for row in rows) / len(rows)
        for field in ALLOWED
    }
    missing_mentions: Counter[str] = Counter()
    for row in rows:
        missing_mentions.update(parse_missing_fields(row["missing_fields"]))

    return {
        "summary_version": "0.1",
        "interpretation": (
            "Descriptive pilot annotations only. Counts are not legal findings, "
            "population estimates, gold labels, or evidence of real incident prevalence."
        ),
        "overall": {
            "annotation_count": len(rows),
            "reviewer_count": len({row["reviewer_id"] for row in rows}),
            "case_count": len(by_case),
            "cases_with_disagreement": cases_with_disagreement,
            "disagreement_rates": {
                field: count / len(by_case) for field, count in cases_with_disagreement.items()
            },
            "unclear_rates": unclear_rates,
            "mean_confidence": sum(int(row["confidence"]) for row in rows) / len(rows),
            "reporting_judgment_pairs": _counts(
                f"{row['under_prompt']}|{row['under_effective_regime']}" for row in rows
            ),
            "missing_field_mentions": dict(sorted(missing_mentions.items())),
        },
        "cases": case_summaries,
    }


def main(argv: Sequence[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--annotations", required=True, type=Path)
    parser.add_argument("--cases", required=True, type=Path)
    parser.add_argument("--out", required=True, type=Path)
    args = parser.parse_args(argv)

    try:
        rows = load_annotations(args.annotations, args.cases)
        result = summarize(rows)
        args.out.parent.mkdir(parents=True, exist_ok=True)
        args.out.write_text(
            json.dumps(result, indent=2, sort_keys=True, ensure_ascii=False) + "\n",
            encoding="utf-8",
        )
    except (RowError, OSError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2

    print(
        f"Wrote descriptive summary for {len(rows)} annotations, "
        f"{result['overall']['reviewer_count']} reviewers, and "
        f"{result['overall']['case_count']} cases to {args.out}"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

import csv
import json
import unittest
from pathlib import Path


ROOT = Path(__file__).parents[1]


class CaseDataTests(unittest.TestCase):
    def setUp(self):
        self.payload = json.loads((ROOT / "data" / "cases.json").read_text(encoding="utf-8"))
        self.cases = self.payload["cases"]

    def test_twelve_unique_versioned_cases(self):
        self.assertEqual(len(self.cases), 12)
        self.assertEqual(len({case["id"] for case in self.cases}), 12)
        for index, case in enumerate(self.cases, start=1):
            self.assertEqual(case["id"], f"HT-{index:03d}")
            self.assertEqual(case["version"], "0.1")
            self.assertGreater(len(case["facts"]), 100)

    def test_template_has_exactly_one_row_per_case(self):
        with (ROOT / "data" / "annotation-template.csv").open(
            newline="", encoding="utf-8"
        ) as handle:
            rows = list(csv.DictReader(handle))
        self.assertEqual([row["case_id"] for row in rows], [case["id"] for case in self.cases])
        for row in rows:
            for field, value in row.items():
                if field != "case_id":
                    self.assertEqual(value, "", f"template is not blank: {field}")

    def test_prompt_limitation_is_traveling_with_data(self):
        self.assertIn("not the full proposed rule", self.payload["source_prompt_scope"])
        self.assertEqual(self.payload["status"], "fictional_design_pilot")


class SchemaStructureTests(unittest.TestCase):
    def setUp(self):
        self.schema = json.loads(
            (ROOT / "schema" / "incident-record.schema.json").read_text(encoding="utf-8")
        )

    def test_local_references_resolve(self):
        definitions = self.schema["$defs"]

        def walk(value):
            if isinstance(value, dict):
                for key, child in value.items():
                    if key == "$ref":
                        self.assertTrue(child.startswith("#/$defs/"))
                        self.assertIn(child.removeprefix("#/$defs/"), definitions)
                    else:
                        walk(child)
            elif isinstance(value, list):
                for child in value:
                    walk(child)

        walk(self.schema)

    def test_required_properties_exist(self):
        def check_object(schema):
            self.assertLessEqual(set(schema.get("required", [])), set(schema["properties"]))
            for child in schema["properties"].values():
                if child.get("type") == "object":
                    check_object(child)

        check_object(self.schema)
        for definition in self.schema["$defs"].values():
            if definition.get("type") == "object":
                check_object(definition)

    def test_sensitive_and_uncertainty_fields_are_explicit(self):
        required = set(self.schema["required"])
        self.assertIn("handling", required)
        self.assertIn("evidence", required)
        self.assertIn("knowledge_status", required)
        unknown = self.schema["$defs"]["unknown"]
        self.assertEqual(set(unknown["required"]), {"field", "why_unknown", "investigation", "due_at"})


if __name__ == "__main__":
    unittest.main()

# Results

**No annotations have been collected and no empirical results exist.**

The presence of `data/annotation-template.csv` is not a result. A future result file must state:

- exact case and rubric versions;
- authoritative prompt or rule excerpts supplied to reviewers;
- number of invited and completed reviewers, recruitment method, and relevant perspectives;
- compensation and conflicts of interest;
- all exclusion decisions;
- original case-level disagreement and uncertainty;
- reconciliation conducted after independent labels were frozen;
- limitations, including nonrepresentative case and reviewer selection.

Do not substitute annotations generated by the project author or an AI system for independent practitioner review. AI-generated synthetic labels may be used only in a separately labeled software test, never as evidence about reporting rules.

